import {render, screen, waitFor} from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import {LoginForm} from './LoginForm'

test('shows a successful login', async () => {
  render(<LoginForm />)
  const user = userEvent.setup()

  await user.click(screen.getByRole('button', {name: /sign in/i}))
  expect(screen.getByRole('status')).toHaveTextContent(/loading/i)

  expect(await screen.findByRole('status')).toHaveTextContent(/signed in/i)
  await waitFor(() =>
    expect(screen.getByRole('heading', {name: /welcome/i})).toBeInTheDocument(),
  )
})

import {render, screen, waitForElementToBeRemoved} from '@testing-library/react'
import App from './App'

test('removes the loading indicator', async () => {
  render(<App />)

  const loading = screen.getByText(/loading/i)
  await waitForElementToBeRemoved(loading)

  expect(screen.getByRole('heading', {name: /results/i})).toBeInTheDocument()
})

import {render, screen, waitFor} from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import {MyForm} from './MyForm'

test('submits entered form values', async () => {
  const onSubmit = jest.fn()
  render(<MyForm onSubmit={onSubmit} />)
  const user = userEvent.setup()

  await user.type(screen.getByRole('textbox', {name: /first name/i}), 'John')
  await user.type(screen.getByRole('textbox', {name: /last name/i}), 'Dee')
  await user.type(screen.getByRole('textbox', {name: /email/i}), 'john@example.com')
  await user.click(screen.getByRole('button', {name: /submit/i}))

  await waitFor(() => expect(onSubmit).toHaveBeenCalledWith({
    firstName: 'John', lastName: 'Dee', email: 'john@example.com',
  }))
})

import {render, screen} from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import {expect, test} from 'vitest'

function Search() {
  return <input aria-label="Search" />
}

test('types into the search field', async () => {
  const user = userEvent.setup()
  render(<Search />)
  const input = screen.getByRole('textbox', {name: 'Search'})

  await user.click(input)
  await user.type(input, 'react testing')
  expect(input).toHaveValue('react testing')
})

import userEvent from '@testing-library/user-event'
import { render, screen } from '@testing-library/react'
import { expect, test } from 'vitest'

function Search() {
  return <input aria-label="Search" onKeyDown={e => {
    if (e.key === 'Enter') e.currentTarget.value = 'submitted'
  }} />
}

test('submits with Enter after typing', async () => {
  const user = userEvent.setup()
  render(<Search />)
  const input = screen.getByRole('textbox', { name: 'Search' })

  await user.click(input)
  await user.keyboard('query{Enter}')
  expect(input).toHaveValue('submitted')
})

