  return (
    <section>
      <p>Saved</p>
      <output data-testid="save-status">Saved</output>
    </section>
  )
}

test('queries visible text and a test id', () => {
  render(<Status />)
  expect(screen.getByText('Saved')).toBeInTheDocument()
  expect(screen.getByTestId('save-status')).toHaveTextContent('Saved')
})

import {render, within} from '@testing-library/react'
import '@testing-library/jest-dom'

function Inbox() {
  return (
    <main>
      <section aria-label="Messages">
        <button>Archive</button>
      </section>
      <section aria-label="Settings">
        <button>Save</button>
      </section>
    </main>
  )
}

test('finds a control within one region', () => {
  render(<Inbox />)
  const messages = within(document.querySelector('[aria-label="Messages"]')!)
  expect(messages.getByRole('button', {name: 'Archive'})).toBeInTheDocument()
})

import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { expect, test } from 'vitest'

function SaveButton() {
  return <button aria-pressed="false">Save</button>
}

test('supports an accessible name and keyboard activation', async () => {
  const user = userEvent.setup()
  render(<SaveButton />)
  const button = screen.getByRole('button', { name: 'Save' })

  expect(button).toHaveAttribute('aria-pressed', 'false')
  await user.tab()
  await user.keyboard('{Enter}')
  expect(button).toHaveFocus()
})

